package com.aoo.bcg.common.retry;import java.time.Duration;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ControlledRetryTest{@Test void retriesOnlyTransientIdempotentCallsWithBoundedBackoff()throws Exception{var delays=new ArrayList<Duration>();var retry=new ControlledRetry(new ControlledRetry.Policy(3,Duration.ofMillis(10),Duration.ofMillis(15),Duration.ofSeconds(1),0.2),delays::add,(base,ratio)->base);var calls=new AtomicInteger();assertEquals("ok",retry.execute("request-1",()->{if(calls.incrementAndGet()<3)throw new java.io.IOException("temporary");return"ok";},e->e instanceof java.io.IOException));assertEquals(List.of(Duration.ofMillis(10),Duration.ofMillis(15)),delays);assertThrows(IllegalArgumentException.class,()->retry.execute("",()->"bad",e->true));calls.set(0);assertThrows(IllegalStateException.class,()->retry.execute("request-2",()->{calls.incrementAndGet();throw new IllegalStateException("permanent");},e->false));assertEquals(1,calls.get());}}
